/* called from fm1_fatal_common (fm1_vec.S) with the saved frame:
 * f[0..15] r0..r15, f[16] reti, f[17] rete, f[18] retx, f[19] stub+6,
 * f[20] psr, f[21] icfg, f[22] usp, f[23] ssp, f[24] sp, f[25] interrupted rets */
void fm1_fault_c(uint32_t *f)
{
    static volatile uint32_t in_fault;
    uint32_t i, count = fm1_crash.magic == FM1_CRASH_MAGIC ? fm1_crash.count : 0;
    uint32_t early = fm1_crash.magic == FM1_CRASH_MAGIC ? fm1_crash.early : 0;
    fm1_irq_off();
    if (in_fault++)                           /* fault while reporting: reset at once */
        *(volatile uint32_t *)0x10000u |= 1u << 4;
    fm1_crash.magic = FM1_CRASH_MAGIC;
    fm1_crash.count = count + 1u;
    fm1_crash.vec = (f[19] - (uint32_t)(uintptr_t)fm1_fatal_stubs) / 6u - 1u;
    fm1_crash.pc = f[16];
    fm1_crash.rets = f[25];
    fm1_crash.emu = FM1_EMU_MSG;
    fm1_crash.dbg = FM1_DBG_MSG;
    fm1_crash.sp = f[24];
    fm1_crash.psr = f[20];
    fm1_crash.icfg = f[21];
    fm1_crash.uptime_ms = *(volatile uint32_t *)0x10804u / 24000u;   /* TIMER4 since boot */
    for (i = 0; i < 4u; i++)
        fm1_crash.etm[i] = FM1_ETM_PC(i);
    fm1_crash.early = fm1_crash.uptime_ms < 3000u ? early + 1u : 0u;
    {
        fm1_crash_ctx_t *x = &fm1_crash_ctx[fm1_crash.count % FM1_CRASH_CTX_N];
        x->count = fm1_crash.count;
        x->pc = f[16];
        for (i = 0; i < 16u; i++)
            x->r[i] = f[i];                   /* frame: r0..r15 first (fm1_vec.S) */
        x->usp = f[22];
        x->ssp = f[23];
    }
    fm1_fault(&fm1_crash);
    for (;;)
        ;
}

static void fm1_adc_start(uint32_t ch, uint32_t con)
{
    FM1_ADC_CON_R = 0;
    if (FM1_WLA_CON0 & (1u << 14))
        FM1_WLA_CON0 &= ~(1u << 14);
    FM1_ADC_CON_R = (con & 0xF00Fu) | 0x40u | ((ch & 0xFu) << 8);
    FM1_ADC_CON_R |= 0x10u;
    FM1_ADC_CON_R |= 0x40u;
}

static int32_t fm1_adc_read(uint32_t ch)
{
    uint32_t t;
    fm1_adc_start(ch, FM1_ADC_CON_SDK);
    for (t = 0; t < 20000u; t++)
        if (fm1_adc_done())
            break;
    if (t == 20000u) {
        fm1_adc_abort();
        return -1;
    }
    return (int32_t)fm1_adc_take();
}

int plat_store_save(uint32_t obj, const void *src, uint32_t len)
{
    store_ready();
    if (obj >= OBJ_NOBJ || len > PLAT_STORE_MAX)
        return -1;
    memcpy(store[obj], src, len);
    store_len[obj] = (int)len;
    store_writes++;
    return 0;
}

/* Velo's settings, as MONK-1 and CTL-1 use them; the curve's exponent x 2 at +5, / 2 at -5 */
static void touch_config(void)
{
    sn_cfg.touch = 900;
    sn_cfg.press = 400;
    sn_cfg.release = 600;
    sn_cfg.wait = 2;
    sn_cfg.v_lo = 0;
    sn_cfg.v_hi = 72;
    sn_cfg.vmax = 127;
    sn_cfg.at_range = 32;
    sn_cfg.drive = 2;
    sn_cfg.d_curve = (uint16_t)(TOUCH_CURVE * fm_exp2f((float)touch_c * 0.2f) + 0.5f);
    sn_cfg.d_ceil = TOUCH_LIGHT;
    sn_cfg.d_floor = TOUCH_FIRM;
    sn_cfg.d_at_range = 64;
    sn_cfg.t_lo = 0;                     /* the top row's probe: */
    sn_cfg.t_hi = 43;                    /* firm presses pile up at 43..45 */
    sn_cfg.t_curve = 240;
    sn_cfg.learn = 0;
}

/* the calibration back to the defaults: the level's floor, LIGHTEST (it belongs to one strength) */
static void sense_cal_reset(void)
{
    uint32_t k;
    for (k = 0; k < SN_NKEYS; k++) {
        sn_cal_put(&sn_key[k], (uint32_t)SN_DFLOOR_DEF << 4, (uint32_t)sn_cfg.d_ceil << 4);
        sn_key[k].nland = 0;
    }
    sn_cal_changed = 1;
}

void touch_on(int on)
{
    on = on != 0;
    touch_config();
    if (on == touch_live)
        return;
    if (on) {
        sense_init(plat_analog_mask());  /* fresh key states: nothing was sampled while off */
        touch_config();
        sense_cal_reset();
    }
    touch_held = 0;
    plat_sense(on);
    touch_live = (uint8_t)on;
}

static float curve_of(int c, float t)
{
    return c == 3 ? 0.78f : fpow(t, CURVE_EXP[c]);
}

void app_init(void)
{
    settings_load();
    slots_load();
    erk_bank_open(&bank, ERK_BANK);
    erk_init(&bank, &ENGINE);
    apply_settings();
}

int sm_sysex(const uint8_t *m, unsigned n)
{
    if (n != 6 || m[0] != 0xf0 || m[1] != 0x7d || m[2] != 'F' || m[3] != 'S' || m[5] != 0xf7)
        return 0;
    sm_name_hello = 1;                 /* every hello also asks for the sound's name */
    if (m[4] != 2)
        sm_hello = 1u + (m[4] == 1);
    return 1;
}

/* rows [y0, y1) back to the background (and marked to send) */
static void restore(int y0, int y1)
{
    int i;
    dirty(y0, y1);
    if (y0 < 0)
        y0 = 0;
    if (y1 > SH)
        y1 = SH;
    for (i = y0 * SW; i < y1 * SW; i++) {
        const uint8_t *c = bgp + 3u * BGI[i];
        W[3 * i] = c[0];
        W[3 * i + 1] = c[1];
        W[3 * i + 2] = c[2];
    }
}

/* lacquer: a dim diffuse term and a broad, soft specular (Blinn) one */
static rgb_t shade(v3 n, rgb_t base, float spec_k, int gloss)
{
    v3 h = {b_light.x + b_view.x, b_light.y + b_view.y, b_light.z + b_view.z};
    float diff, sp, r, g, b, k = 1;
    int i;
    n = norm3(rot3(n));
    h = norm3(h);
    diff = dot3(n, b_light);
    diff = diff > 0 ? diff : 0;
    sp = dot3(n, h);
    sp = sp > 0 ? sp : 0;
    for (i = 0; i < gloss; i++)
        k *= sp;
    r = base.r * (0.55f + 0.7f * diff) + 96 * k * spec_k;
    g = base.g * (0.55f + 0.7f * diff) + 96 * k * spec_k;
    b = base.b * (0.55f + 0.7f * diff) + 106 * k * spec_k;
    return C3((uint8_t)(r > 255 ? 255 : r), (uint8_t)(g > 255 ? 255 : g), (uint8_t)(b > 255 ? 255 : b));
}

static void lozenge(float cx, float cy, float r, rgb_t c, float alpha, int outline)
{
    float p[8] = {cx + 0.5f, cy - r + 0.5f, cx + r + 0.5f, cy + 0.5f, cx + 0.5f, cy + r + 0.5f, cx - r + 0.5f, cy + 0.5f};
    mask_clear((int)(cx - r) - 2, (int)(cy - r) - 2, (int)(cx + r) + 3, (int)(cy + r) + 3);
    if (outline) {
        float q[10] = {p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], p[0], p[1]};
        int i;
        for (i = 0; i < 10; i++)
            q[i] -= 0.5f;
        mask_line(q, 5, 1.0f);
    } else {
        mask_poly(p, 4);
    }
    mask_fill(c, alpha);
}

static int note_sost(int note)
{
    int k = note - ERK_KEY0;
    return k >= 0 && k < ERK_KEYS && (erk_sost_keys[k >> 5] >> (k & 31) & 1u);
}

/* main loop, outside a session: answer handshakes */
static void ota_service(void)
{
    uint32_t d = ota_take();
    if (d == 7u && ota_dec[2] == 0x11)
        ota_reply_identity();
}

void fm1_cstart(void)
{
    uint32_t *s, *d, p3, src, wdt;
    fm1_time_init();
    fm1_reset_reason();
    p3 = fm1_boot.p3_rst;
    if (p3 & 4u)
        wdt_stage = fm1b_dbg.stage;                 /* a watchdog reset: where the loop was (the log readout) */
    src = fm1_boot.rst_src;
    wdt = fm1_boot.wdt_con;
    fm1_wdt_arm(0x0D);
    if (bootguard.magic != BOOTGUARD_MAGIC) {
        bootguard.magic = BOOTGUARD_MAGIC;
        bootguard.failed = 0;
        bootguard.pending = 0;
    }
    if (bootguard.pending)
        bootguard.failed++;
    bootguard.pending = 1;
    if (bootguard.failed >= 4u) {                   /* safe mode failed too: the chip's own update mode */
        bootguard.failed = 0;
        bootguard.pending = 0;
        fm1_enter_uboot();
    }
    p3 |= (bootguard.failed >= 2u) << 8;            /* two failed boots: safe mode (kept past the .bss clear) */
    fm1_irq_init();
    for (d = _bss_start; d < _bss_end; d++)
        *d = 0;
    for (d = _pool_start; d < _pool_end; d++)
        *d = 0;
    for (s = _data_load, d = _data_start; d < _data_end; s++, d++)
        *d = *s;
    for (s = _rt_load, d = _rt_start; d < _rt_end; s++, d++)
        *d = *s;
    fm1_mailbox_clear();
    fm1_guard_enable(FM1_GUARD_STACK | FM1_GUARD_WRITE | FM1_GUARD_BUS | FM1_GUARD_PC);
    safe_mode = (uint8_t)(p3 >> 8);
    fm1_boot.p3_rst = (uint8_t)p3;
    fm1_boot.rst_src = src;
    fm1_boot.wdt_con = (uint8_t)wdt;
    fm1_main();
    for (;;)
        ;
}
